import csv
import io

def load_cases(csv_text):
    cases = []
    for row in csv.DictReader(io.StringIO(csv_text)):
        email = (row.get('email') or '').strip()
        flag = (row.get('valid') or '').strip().lower()
        if not email and not flag:
            continue
        if flag not in ('true', 'false'):
            raise ValueError('bad valid flag')
        cases.append((email, flag == 'true'))
    return cases

