from itertools import combinations, product

def uncovered_pairs(params, rows):
    names = sorted(params)
    missing = []
    for n1, n2 in combinations(names, 2):
        for v1, v2 in product(params[n1], params[n2]):
            if not any(r[n1] == v1 and r[n2] == v2 for r in rows):
                missing.append((n1, v1, n2, v2))
    return sorted(missing)

